head.script:
// 활성화시킬 날짜(Jira 첨부 cal_enable_shb.xml 시나리오)
scwin.dateEnabled = ["20170608", "20170621", "20170629", "20170713", "20170721"];
scwin.cur = { y: "2017", m: 7 };
scwin.log = [];
scwin.enableDate = function() {
	var cells = document.querySelectorAll("[id$='inputCal1_calendar'] .w2calendar_col_date");
	for (var i = 0; i < cells.length; i++) {
		cells[i].classList.add("date_diabled");
	}
	for (var j = 0; j < scwin.dateEnabled.length; j++) {
		var d = scwin.dateEnabled[j];
		if (d.substr(0, 4) == scwin.cur.y && Number(d.substr(4, 2)) == Number(scwin.cur.m)) {
			var t = document.querySelectorAll("[id$='inputCal1_calendar'] .w2calendar_date_" + Number(d.substr(6, 2)));
			for (var k = 0; k < t.length; k++) {
				t[k].classList.remove("date_diabled");
			}
		}
	}
};
scwin.inputCal1_oniconclick = function(e) {
	scwin.log.push("oniconclick");
	setTimeout(scwin.enableDate, 10);
};
scwin.inputCal1_onmonthselect = function(info) {
	scwin.log.push("onmonthselect:" + info.oldValue + ">" + info.newValue);
	scwin.cur.m = info.newValue;
	setTimeout(scwin.enableDate, 10);
};
scwin.inputCal1_onyearselect = function(info) {
	scwin.log.push("onyearselect:" + info.oldValue + ">" + info.newValue);
	scwin.cur.y = String(info.newValue);
	setTimeout(scwin.enableDate, 10);
};
scwin.onpageload = function() {
	inputCal1.setValue("20170715");
};
